/**
 * Core Verifiers - The proof engine
 *
 * Per PRD: Verifiers are triggered deterministically but evaluated agentically.
 * They produce PASS/FAIL + evidence, enabling honest capability assessment.
 *
 * No verifier = not proven. Self-report does not count.
 */

import { exec } from 'child_process';
import { promisify } from 'util';
import { existsSync, readFileSync, readdirSync } from 'fs';
import path from 'path';

const execAsync = promisify(exec);

/**
 * Known framework/agent artifacts that should be excluded from git status checks.
 * These files are generated by the agent framework, not by the worker.
 */
const FRAMEWORK_ARTIFACT_PATTERNS = [
  /^STEP-\d+-COMPLETE\.md$/,
  /^RESEARCH\.md$/,
  /^PLAN\.md$/,
  /^NOTES\.md$/,
  /\.handoff\.md$/,
];

/**
 * Path prefixes for directories that contain agent/tool artifacts (not worker code).
 * Files under these paths are excluded from git_status_clean checks.
 */
const ARTIFACT_DIR_PREFIXES = [
  '.playwright-cli/',
  '.playwright-mcp/',
];

/**
 * Detect the actual git project root within an output_path.
 * Workers sometimes create apps in a subdirectory (e.g., output_path/music-player/).
 * Returns the subdirectory path if a .git dir is found there, or null.
 */
function findSubdirectoryGitRoot(projectPath: string): string | null {
  try {
    const entries = readdirSync(projectPath, { withFileTypes: true });
    for (const entry of entries) {
      if (!entry.isDirectory() || entry.name.startsWith('.')) continue;
      const subDir = path.join(projectPath, entry.name);
      if (existsSync(path.join(subDir, '.git'))) {
        return subDir;
      }
    }
  } catch {
    // ignore
  }
  return null;
}

/**
 * Filter out known framework artifacts from git status output lines.
 */
function filterFrameworkArtifacts(changedFiles: string[]): string[] {
  return changedFiles.filter(line => {
    // Extract the full relative path from git status line (format: "XY path/to/file")
    const filePath = line.replace(/^.{2}\s+/, '').replace(/^"(.*)"$/, '$1');
    const fileName = filePath.split('/').pop() || '';

    // Exclude files matching known framework artifact patterns
    if (FRAMEWORK_ARTIFACT_PATTERNS.some(pattern => pattern.test(fileName))) return false;

    // Exclude files under known artifact directories
    if (ARTIFACT_DIR_PREFIXES.some(prefix => filePath.startsWith(prefix))) return false;

    return true;
  });
}

export interface VerifierResult {
  verifier_id: string;
  result: 'PASS' | 'FAIL';
  message: string;
  evidence: Record<string, unknown>;
  duration_ms: number;
}

export interface VerifierConfig {
  project_path: string;
  timeout_ms?: number;
}

/**
 * Step context for step-aware validation
 */
export interface StepContext {
  step_number: number;
  step_title: string;
  total_steps: number;
}

/**
 * Determine step type from step title and number
 * Research/planning steps get lighter validation
 */
function getStepType(step?: StepContext): 'research' | 'setup' | 'implementation' | 'testing' | 'unknown' {
  if (!step) return 'unknown';

  const title = step.step_title.toLowerCase();

  // Step 1 is typically research/planning
  if (step.step_number === 0 ||
      title.includes('research') ||
      title.includes('plan') ||
      title.includes('analyze') ||
      title.includes('investigate')) {
    return 'research';
  }

  // Setup/initialization step
  if (title.includes('initialize') ||
      title.includes('setup') ||
      title.includes('scaffold') ||
      title.includes('project structure')) {
    return 'setup';
  }

  // Testing step
  if (title.includes('test') ||
      title.includes('quality') ||
      title.includes('qa')) {
    return 'testing';
  }

  // Default to implementation for other steps
  return 'implementation';
}

/**
 * Verifier 1: git_status_clean
 * Checks that the git working tree is clean (no uncommitted changes)
 */
export async function verifyGitStatusClean(config: VerifierConfig): Promise<VerifierResult> {
  const start = Date.now();
  let { project_path } = config;

  try {
    // Check if project_path itself is a git repo
    const hasGitDir = existsSync(path.join(project_path, '.git'));

    if (!hasGitDir) {
      // Workers sometimes create apps in a subdirectory of output_path.
      // Look for a subdirectory that contains .git/
      const subRoot = findSubdirectoryGitRoot(project_path);
      if (subRoot) {
        project_path = subRoot;
      } else {
        // No git repo found at all — this is acceptable, not a failure
        return {
          verifier_id: 'git_status_clean',
          result: 'PASS',
          message: 'No git repository found (project may not use git)',
          evidence: { clean: true, no_git: true },
          duration_ms: Date.now() - start,
        };
      }
    }

    const { stdout } = await execAsync('git status --porcelain', {
      cwd: project_path,
      timeout: config.timeout_ms || 10000,
    });

    const rawChangedFiles = stdout.trim().split('\n').filter(Boolean);
    // Filter out known agent framework artifacts
    const changedFiles = filterFrameworkArtifacts(rawChangedFiles);
    const isClean = changedFiles.length === 0;

    return {
      verifier_id: 'git_status_clean',
      result: isClean ? 'PASS' : 'FAIL',
      message: isClean ? 'Working tree is clean' : `${changedFiles.length} uncommitted changes`,
      evidence: {
        clean: isClean,
        changed_files: changedFiles.slice(0, 10),
        ...(project_path !== config.project_path ? { actual_git_root: project_path } : {}),
        ...(rawChangedFiles.length !== changedFiles.length ? { filtered_artifacts: rawChangedFiles.length - changedFiles.length } : {}),
      },
      duration_ms: Date.now() - start,
    };
  } catch (error) {
    return {
      verifier_id: 'git_status_clean',
      result: 'FAIL',
      message: `Git check failed: ${error instanceof Error ? error.message : String(error)}`,
      evidence: { error: true },
      duration_ms: Date.now() - start,
    };
  }
}

/**
 * Verifier 2: commit_exists
 * Checks that at least one commit exists in the repo
 */
export async function verifyCommitExists(config: VerifierConfig): Promise<VerifierResult> {
  const start = Date.now();
  const { project_path } = config;

  try {
    const { stdout } = await execAsync('git log --oneline -5', {
      cwd: project_path,
      timeout: config.timeout_ms || 10000,
    });

    const commits = stdout.trim().split('\n').filter(Boolean);
    const hasCommits = commits.length > 0;

    return {
      verifier_id: 'commit_exists',
      result: hasCommits ? 'PASS' : 'FAIL',
      message: hasCommits ? `Found ${commits.length} recent commits` : 'No commits found',
      evidence: {
        commit_count: commits.length,
        recent_commits: commits.slice(0, 5),
      },
      duration_ms: Date.now() - start,
    };
  } catch (error) {
    return {
      verifier_id: 'commit_exists',
      result: 'FAIL',
      message: `Git log failed: ${error instanceof Error ? error.message : String(error)}`,
      evidence: { error: true },
      duration_ms: Date.now() - start,
    };
  }
}

/**
 * Verifier 3: files_exist
 * Checks that required files exist
 */
export async function verifyFilesExist(
  config: VerifierConfig,
  requiredFiles: string[]
): Promise<VerifierResult> {
  const start = Date.now();
  const { project_path } = config;

  const results: Record<string, boolean> = {};
  const missing: string[] = [];

  for (const file of requiredFiles) {
    const fullPath = path.join(project_path, file);
    const exists = existsSync(fullPath);
    results[file] = exists;
    if (!exists) {
      missing.push(file);
    }
  }

  const allExist = missing.length === 0;

  return {
    verifier_id: 'files_exist',
    result: allExist ? 'PASS' : 'FAIL',
    message: allExist ? `All ${requiredFiles.length} required files exist` : `Missing: ${missing.join(', ')}`,
    evidence: {
      files_checked: results,
      missing,
    },
    duration_ms: Date.now() - start,
  };
}

/**
 * Verifier 4: node_install
 * Checks that npm install/ci succeeds
 */
export async function verifyNodeInstall(config: VerifierConfig): Promise<VerifierResult> {
  const start = Date.now();
  const { project_path } = config;

  // Check if package.json exists
  const packageJsonPath = path.join(project_path, 'package.json');
  if (!existsSync(packageJsonPath)) {
    return {
      verifier_id: 'node_install',
      result: 'FAIL',
      message: 'No package.json found',
      evidence: { package_json_exists: false },
      duration_ms: Date.now() - start,
    };
  }

  try {
    // Use npm ci for reproducible installs, fall back to npm install
    const { stdout, stderr } = await execAsync('npm ci || npm install', {
      cwd: project_path,
      timeout: config.timeout_ms || 120000, // 2 min timeout
    });

    return {
      verifier_id: 'node_install',
      result: 'PASS',
      message: 'npm install succeeded',
      evidence: {
        stdout: stdout.slice(-500),
        stderr: stderr.slice(-500),
      },
      duration_ms: Date.now() - start,
    };
  } catch (error) {
    const errorMsg = error instanceof Error ? error.message : String(error);
    return {
      verifier_id: 'node_install',
      result: 'FAIL',
      message: `npm install failed: ${errorMsg.slice(0, 200)}`,
      evidence: {
        error: errorMsg.slice(0, 1000),
      },
      duration_ms: Date.now() - start,
    };
  }
}

/**
 * Verifier 5: node_build
 * Checks that npm run build succeeds
 */
export async function verifyNodeBuild(config: VerifierConfig): Promise<VerifierResult> {
  const start = Date.now();
  const { project_path } = config;

  // Check if build script exists
  const packageJsonPath = path.join(project_path, 'package.json');
  if (!existsSync(packageJsonPath)) {
    return {
      verifier_id: 'node_build',
      result: 'FAIL',
      message: 'No package.json found',
      evidence: { package_json_exists: false },
      duration_ms: Date.now() - start,
    };
  }

  try {
    const packageJson = JSON.parse(readFileSync(packageJsonPath, 'utf-8'));
    if (!packageJson.scripts?.build) {
      return {
        verifier_id: 'node_build',
        result: 'FAIL',
        message: 'No build script in package.json',
        evidence: { has_build_script: false },
        duration_ms: Date.now() - start,
      };
    }
  } catch (e) {
    return {
      verifier_id: 'node_build',
      result: 'FAIL',
      message: 'Failed to parse package.json',
      evidence: { parse_error: true },
      duration_ms: Date.now() - start,
    };
  }

  try {
    const { stdout, stderr } = await execAsync('npm run build', {
      cwd: project_path,
      timeout: config.timeout_ms || 300000, // 5 min timeout
    });

    return {
      verifier_id: 'node_build',
      result: 'PASS',
      message: 'Build succeeded',
      evidence: {
        stdout: stdout.slice(-500),
        stderr: stderr.slice(-500),
      },
      duration_ms: Date.now() - start,
    };
  } catch (error) {
    const errorMsg = error instanceof Error ? error.message : String(error);
    return {
      verifier_id: 'node_build',
      result: 'FAIL',
      message: `Build failed: ${errorMsg.slice(0, 200)}`,
      evidence: {
        error: errorMsg.slice(0, 1000),
      },
      duration_ms: Date.now() - start,
    };
  }
}

/**
 * Verifier 6: node_test
 * Checks that npm test succeeds (if tests exist)
 */
export async function verifyNodeTest(config: VerifierConfig): Promise<VerifierResult> {
  const start = Date.now();
  const { project_path } = config;

  const packageJsonPath = path.join(project_path, 'package.json');
  if (!existsSync(packageJsonPath)) {
    return {
      verifier_id: 'node_test',
      result: 'FAIL',
      message: 'No package.json found',
      evidence: { package_json_exists: false },
      duration_ms: Date.now() - start,
    };
  }

  try {
    const packageJson = JSON.parse(readFileSync(packageJsonPath, 'utf-8'));
    if (!packageJson.scripts?.test || packageJson.scripts.test === 'echo "Error: no test specified" && exit 1') {
      // No tests configured - this is a PASS with note
      return {
        verifier_id: 'node_test',
        result: 'PASS',
        message: 'No test script configured (acceptable for MVP)',
        evidence: { has_test_script: false, note: 'No tests to run' },
        duration_ms: Date.now() - start,
      };
    }
  } catch (e) {
    return {
      verifier_id: 'node_test',
      result: 'FAIL',
      message: 'Failed to parse package.json',
      evidence: { parse_error: true },
      duration_ms: Date.now() - start,
    };
  }

  try {
    const { stdout, stderr } = await execAsync('npm test', {
      cwd: project_path,
      timeout: config.timeout_ms || 120000, // 2 min timeout
    });

    return {
      verifier_id: 'node_test',
      result: 'PASS',
      message: 'Tests passed',
      evidence: {
        stdout: stdout.slice(-500),
        stderr: stderr.slice(-500),
      },
      duration_ms: Date.now() - start,
    };
  } catch (error) {
    const errorMsg = error instanceof Error ? error.message : String(error);
    return {
      verifier_id: 'node_test',
      result: 'FAIL',
      message: `Tests failed: ${errorMsg.slice(0, 200)}`,
      evidence: {
        error: errorMsg.slice(0, 1000),
      },
      duration_ms: Date.now() - start,
    };
  }
}

